      "path": "lib/plugin/config.js",
      "content": "/**\n * plugin/config.js — 插件配置面（L5，零 DSH API / 零第三方依赖）\n *\n * 只暴露三个低风险字段：\n *   - maxResults:  design_search 未显式传 maxResults 时的默认值（1–8）\n *   - reviewRules: design_review 未显式传 maxRules 时的默认值（1–20）\n *   - skill:       是否注册内置 ui-ux-pro-max 技能\n *\n * 同时导出 Standard Schema 形状的 `Config`，让 Cordis 的 resolveConfig()\n * 在加载期校验；`apply()` 内会再 normalize 一次，保证直接调用也安全。\n */\n\nexport const DEFAULT_CONFIG = Object.freeze({\n  maxResults: 3,\n  reviewRules: 8,\n  skill: true,\n})\n\n/**\n * 校验并规范化配置。未知字段被忽略；类型错误直接抛 TypeError。\n * @param {unknown} raw\n */\nexport function normalizeConfig(raw = {}) {\n  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) {\n    throw new TypeError('config 必须是对象')\n  }\n  const value = { ...DEFAULT_CONFIG, ...raw }\n  const int = (name, min, max) => {\n    const n = value[name]\n    if (!Number.isInteger(n) || n < min || n > max) {\n      throw new TypeError(`${name} 必须是 ${min}-${max} 的整数`)\n    }\n    return n\n  }\n  if (typeof value.skill !== 'boolean') throw new TypeError('skill 必须是布尔值')\n  return Object.freeze({\n    maxResults: int('maxResults', 1, 8),\n    reviewRules: int('reviewRules', 1, 20),\n    skill: value.skill,\n  })\n}\n\n/**\n * 给工具 spec 注入配置默认值。用户显式传入的参数优先。\n * 只处理有“默认条数”语义的两个工具；design_recommend 原样返回。\n * @param {object} spec\n * @param {{maxResults:number, reviewRules:number}} config\n */\nexport function applyToolDefaults(spec, config) {\n  const defaults = spec.name === 'design_search'\n    ? { maxResults: config.maxResults }\n    : spec.name === 'design_review'\n      ? { maxRules: config.reviewRules }\n      : null\n  if (!defaults) return spec\n  return {\n    ...spec,\n    async execute(args = {}, exec) {\n      return spec.execute({ ...defaults, ...args }, exec)\n    },\n  }\n}\n\n/**\n * Standard Schema 适配层。Cordis 4.x 的 resolveConfig() 读取\n * `runtime.Config['~standard'].validate(config)`。\n */\nexport const Config = {\n  '~standard': {\n    version: 1,\n    vendor: 'dsh-ui-ux-pro-max',\n    validate(value = {}) {\n      try {\n        return { value: normalizeConfig(value) }\n      } catch (error) {\n        return { issues: [{ message: error.message, path: [] }] }\n      }\n    },\n  },\n}\n"
    },
    {
      "path": "lib/tools/design-recommend.js",
      "content": "/**\n * design-recommend.js — design_recommend 工具定义（L4）\n *\n * 只声明宿主无关的工具规格：parameters / output schema / execute /\n * render / presentCall / presentResult。DSH 的 defineTool 由 plugin/index.js\n * 统一套用（宿主 API 只出现在 plugin/）。\n */\n\nimport { RENDER, TIMEOUTS } from '../config.js'\nimport { generateDesignSystem, summarizeDesignSystem } from '../domain/design-system.js'\nimport { clampMarkdown, formatDesignSystem, formatTokenSummary } from '../presentation/index.js'\nimport { STACKS } from '../repo/stacks.js'\nimport { array, integer, nullableObject, object, stringEnum, text } from './schema.js'\n\nexport const designRecommendTool = {\n  name: 'design_recommend',\n  description:\n    '根据产品类型 + 关键词生成完整设计系统建议：推荐设计风格（按优先级排序）、配色方案（HEX 令牌）、' +\n    '字体搭配、落地页模式、UX 规范要点，并给出选择理由与反模式。中文查询自动映射到设计数据库。' +\n    '创建新项目/页面、选择风格/配色/字体时使用。可选 stack 附加技术栈规范，可选 variance/motion/density' +\n    '三个 1-10 旋钮调整大胆度/动效/密度。',\n  timeoutMs: TIMEOUTS.designRecommend,\n  isConcurrencySafe: () => true,\n  parameters: {\n    query: text('产品类型 + 行业 + 气质，如「财务 数据看板 深色」「beauty spa 疗愈」「AI 搜索 极简」', true),\n    projectName: text('项目名称（可选，用于输出标题）'),\n    stack: stringEnum(STACKS, '技术栈键（可选），附加该技术栈的实现规范'),\n    variance: integer('大胆度旋钮 1-10：1=居中/极简，10=大胆/不对称（可选）'),\n    motion: integer('动效旋钮 1-10：1=克制，10=复杂编排，会附加 GSAP 动效方案（可选）'),\n    density: integer('密度旋钮 1-10：1=宽松，10=紧凑/看板，会覆盖间距刻度（可选）'),\n  },\n  output: {\n    schema: {\n      type: 'object',\n      additionalProperties: true,\n      properties: {\n        projectName: { type: 'string', required: true },\n        category: { type: 'string', required: true },\n        pattern: object({}, { required: true, description: '落地页模式（名称/区块顺序/CTA 位置）' }),\n        styles: array({ type: 'object', additionalProperties: true }, '推荐风格（按优先级排序）', true),\n        colors: object({}, { required: true, description: 'HEX 配色令牌与 CSS 变量' }),\n        typography: object({}, { required: true, description: '字体搭配' }),\n        keyEffects: text('关键效果'),\n        antiPatterns: array({ type: 'string' }, '反模式'),\n        reasoning: object({}, { description: '选择理由与决策规则' }),\n        uxGuidelines: array({ type: 'object', additionalProperties: true }, 'UX 规范要点'),\n        stackGuidelines: array({ type: 'object', additionalProperties: true }, '技术栈规范'),\n        dials: object({}, { description: '三个设计旋钮的解析结果' }),\n        motionSnippet: nullableObject,\n        spacingScale: nullableObject,\n        implementationChecklist: array({ type: 'string' }, '实现清单'),\n        designSystemVariables: text('设计系统变量'),\n      },\n    },\n    render(_args, value) {\n      return [{ type: 'text', text: clampMarkdown(formatDesignSystem(value), RENDER.designSystemChars) }]\n    },\n    /** 完成态卡片摘要（持久化到 tool/result，供 presentResult 使用） */\n    presentationMeta(_args, value) {\n      return summarizeDesignSystem(value)\n    },\n  },\n  /** 同步 CPU 实现；不观察 exec.signal（见 docs/DSH-COMPAT.md §4.4）。 */\n  async execute(args) {\n    const ds = generateDesignSystem({\n      query: args.query,\n      projectName: args.projectName,\n      variance: args.variance,\n      motion: args.motion,\n      density: args.density,\n      stack: args.stack,\n    })\n    ds.stackName = args.stack || null\n    return ds\n  },\n  presentCall(args) {\n    return {\n      card: 'generic',\n      title: `生成设计系统：${args.query}`,\n      kind: 'search',\n      rawInput: args,\n    }\n  },\n  presentResult(args, result) {\n    const summary = result?.meta\n    if (result?.isError || !summary || typeof summary !== 'object') return undefined\n    return {\n      card: 'generic',\n      title: `设计系统：${summary.projectName || args.query}`,\n      content: [{ type: 'text', text: formatTokenSummary(summary) }],\n    }\n  },\n}\n"
    },
    {
      "path": "lib/tools/design-review.js",
      "content": "/**\n * design-review.js — design_review 工具定义（L4）\n */\n\nimport { LIMITS, TIMEOUTS } from '../config.js'\nimport { buildReview } from '../domain/review.js'\nimport { SEVERITY_LABELS } from '../i18n/index.js'\nimport { formatReview } from '../presentation/index.js'\nimport { array, integer, object, stringEnum, text } from './schema.js'\nimport { getStats } from '../repo/stats.js'\n\n// 能力数字用于描述文案；meta.json 不可读时降级为不含数字的措辞，\n// 而不是让 `undefined 条` 出现在工具描述里。\nconst uxCount = getStats()?.capabilities?.uxGuidelines\nconst uxSources = uxCount\n  ? `${uxCount} 条 UX 规范 + 移动端接口规范 + React 性能规范`\n  : 'UX 规范、移动端接口规范与 React 性能规范'\n\nexport const designReviewTool = {\n  name: 'design_review',\n  description:\n    '按 UX 规范清单审查现有 UI：根据审查对象描述（页面/组件类型、关键词、平台）从 ' +\n    `${uxSources}数据库中检索针对性规则，按严重度（严重/高/中/低）排序，` +\n    '并附上交付前通用检查清单（视觉质量/交互/深浅色模式/布局/无障碍/性能/表单/导航）。' +\n    '评审页面、检查无障碍、优化交互体验时使用。',\n  timeoutMs: TIMEOUTS.designReview,\n  isConcurrencySafe: () => true,\n  parameters: {\n    target: text('页面 + 现象，如「移动端登录页，提交后没有任何反馈」「数据看板首屏加载慢」「pricing 页 转化低」', true),\n    platform: stringEnum(['web', 'mobile', 'desktop', 'react-native', 'flutter'], '目标平台（可选，默认 web）'),\n    maxRules: integer('返回的针对性规范条数上限（可选，默认 8）'),\n  },\n  output: {\n    schema: {\n      type: 'object',\n      additionalProperties: true,\n      properties: {\n        target: { type: 'string', required: true },\n        platform: { type: 'string' },\n        summary: object({\n          matchedRules: { type: 'integer', required: true },\n          bySeverity: object({}),\n          checklistSections: { type: 'integer' },\n        }, { required: true }),\n        priorityRules: array({\n          type: 'object',\n          additionalProperties: true,\n          properties: {\n            category: { type: 'string' },\n            issue: { type: 'string' },\n            platform: { type: 'string' },\n            description: { type: 'string' },\n            do: { type: 'string' },\n            dont: { type: 'string' },\n            severity: { type: 'string', enum: ['Critical', 'High', 'Medium', 'Low'] },\n            source: { type: 'string' },\n            score: { type: 'number' },\n          },\n        }, '针对性规范（按严重度排序）', true),\n        checklist: array({\n          type: 'object',\n          additionalProperties: true,\n          properties: {\n            category: { type: 'string' },\n            checks: { type: 'array', items: { type: 'string' } },\n          },\n        }, '交付前通用检查清单', true),\n      },\n    },\n    render(_args, value) {\n      return [{ type: 'text', text: formatReview(value) }]\n    },\n    /** 持久化到 tool/result 的轻量摘要，供 presentResult 重放。 */\n    presentationMeta(_args, value) {\n      return {\n        target: value.target,\n        matchedRules: value.summary.matchedRules,\n        bySeverity: value.summary.bySeverity,\n        top: value.priorityRules.slice(0, 3).map(rule => ({\n          severity: rule.severity,\n          category: rule.category,\n          issue: rule.issue,\n        })),\n      }\n    },\n  },\n  /** 同步 CPU 实现；不观察 exec.signal（见 docs/DSH-COMPAT.md §4.4）。 */\n  async execute(args) {\n    return buildReview({\n      target: args.target,\n      platform: args.platform || 'web',\n      maxRules: args.maxRules || LIMITS.defaultReviewRules,\n    })\n  },\n  presentCall(args) {\n    return {\n      card: 'generic',\n      title: `审查 UX：${args.target}`,\n      kind: 'search',\n      rawInput: args,\n    }\n  },\n  presentResult(_args, result) {\n    if (result?.isError) return undefined\n    const meta = result?.meta\n    if (!meta || typeof meta !== 'object') return undefined\n    const lines = [`**命中规范：** ${meta.matchedRules} 条`]\n    const severity = Object.entries(meta.bySeverity || {})\n      .filter(([, count]) => count > 0)\n      .map(([level, count]) => `${SEVERITY_LABELS[level] || level} ${count}`)\n    if (severity.length) lines.push(`- 严重度：${severity.join(' / ')}`)\n    for (const rule of meta.top || []) {\n      const label = SEVERITY_LABELS[rule.severity] || rule.severity\n      lines.push(`- [${label}] ${rule.category}｜${rule.issue}`)\n    }\n    return { card: 'generic', title: `审查：${meta.target}`, content: [{ type: 'text', text: lines.join('\\n') }] }\n  },\n}\n"
    },
    {
      "path": "lib/tools/design-search.js",
      "content": "/**\n * design-search.js — design_search 工具定义（L4）\n */\n\nimport { LIMITS, TIMEOUTS } from '../config.js'\nimport { DOMAIN_LABELS } from '../i18n/index.js'\nimport { formatSearchResult } from '../presentation/index.js'\nimport { DOMAIN_KEYS } from '../repo/domains.js'\nimport { getStats } from '../repo/stats.js'\nimport { STACKS } from '../repo/stacks.js'\nimport { search, searchStack } from '../search/retriever.js'\nimport { array, integer, object, stringEnum, text } from './schema.js'\n\nconst stackCount = getStats()?.capabilities?.stacks\n\n/** 卡片里用一行标签代表一个结果行；只取短字段，不把整行塞进 meta。 */\nfunction compactRowLabel(row) {\n  return row['Style Category'] || row['Product Type'] || row['Best Chart Type'] || row['Pattern Name'] ||\n    row['Font Pairing Name'] || row['Icon Name'] || row.Guideline || row.Issue || row.Family ||\n    row.Category || ''\n}\n\nexport const designSearchTool = {\n  name: 'design_search',\n  description:\n    '在 UI/UX 设计智能库中按领域或技术栈检索：风格、配色、图表、落地页、产品类型、UX 规范、字体搭配、' +\n    `图标、动效(GSAP)、React 性能、移动端接口规范、Google 字体，或 ${stackCount} 个技术栈之一。` +\n    '返回按相关度排序的中文结构化结果。中文查询自动映射到英文语料。',\n  timeoutMs: TIMEOUTS.designSearch,\n  isConcurrencySafe: () => true,\n  parameters: {\n    query: text('检索关键词，如「毛玻璃 深色」「表单 校验 无障碍」「safe area 安全区」', true),\n    domain: stringEnum(DOMAIN_KEYS, '领域键（可选）：style/color/chart/landing/product/ux/typography/icons/gsap/react/web/google-fonts'),\n    stack: stringEnum(STACKS, '技术栈键（可选，与 domain 二选一）：如 react/nextjs/vue/flutter/swiftui/javafx'),\n    maxResults: integer('返回条数上限（可选，默认 3）'),\n    includeDeprecated: { type: 'boolean', description: '是否包含 deprecated 条目（可选，默认 false；仅 style/stack 有该状态）' },\n  },\n  output: {\n    schema: {\n      type: 'object',\n      additionalProperties: true,\n      properties: {\n        domain: { type: 'string', required: true },\n        stack: { type: 'string' },\n        query: { type: 'string', required: true },\n        count: { type: 'integer', required: true },\n        results: array({\n          type: 'object',\n          additionalProperties: true,\n          properties: {\n            row: object({}),\n            score: { type: 'number' },\n            fallback: { type: 'boolean', description: '单字查询的领域默认条目（非精确命中）' },\n          },\n        }, '按相关度排序的检索结果', true),\n      },\n    },\n    render(_args, value) {\n      return [{ type: 'text', text: formatSearchResult(value) }]\n    },\n    /** 持久化到 tool/result 的轻量摘要，供 presentResult 重放。 */\n    presentationMeta(_args, value) {\n      return {\n        domain: value.domain,\n        count: value.count,\n        query: value.query,\n        top: value.results.slice(0, 3).map(({ row, score, fallback }) => ({\n          label: compactRowLabel(row),\n          score,\n          fallback: Boolean(fallback),\n        })),\n      }\n    },\n  },\n  /** 同步 CPU 实现；不观察 exec.signal（见 docs/DSH-COMPAT.md §4.4）。 */\n  async execute(args) {\n    const maxResults = Math.max(1, Math.min(LIMITS.maxResults, args.maxResults || LIMITS.defaultResults))\n    const options = { includeDeprecated: args.includeDeprecated === true }\n    if (args.stack) {\n      const result = searchStack(args.query, args.stack, maxResults, options)\n      if (result.error) throw new Error(result.error)\n      return result\n    }\n    return search(args.query, args.domain, maxResults, options)\n  },\n  presentCall(args) {\n    return {\n      card: 'generic',\n      title: `检索设计库：${args.query}${args.domain ? `（${DOMAIN_LABELS[args.domain] || args.domain}）` : ''}`,\n      kind: 'search',\n      rawInput: args,\n    }\n  },\n  presentResult(_args, result) {\n    if (result?.isError) return undefined\n    const meta = result?.meta\n    if (!meta || typeof meta !== 'object') return undefined\n    const lines = [`**命中：** ${meta.count} 条（${meta.domain}）`]\n    for (const item of meta.top || []) {\n      const score = typeof item.score === 'number' ? item.score.toFixed(2) : '—'\n      lines.push(`- ${item.label || '(未命名)'}（${score}）${item.fallback ? ' · 默认条目' : ''}`)\n    }\n    return { card: 'generic', title: `检索：${meta.query}`, content: [{ type: 'text', text: lines.join('\\n') }] }\n  },\n}\n"
    },
    {
      "path": "lib/domain/design-system.js",
      "content": "/**\n * design-system.js — 设计系统生成流程（L3 业务层）\n *\n * 移植自上游 design_system.py（DesignSystemGenerator）：\n *   1. 产品搜索确定类别 → 2. 推理规则 → 3. 多领域检索\n *   (style/color/landing/typography) → 4. 按风格优先级挑选最佳匹配 →\n *   5. 组装结构化中文结果（含理由、反模式、UX 规范、实现清单）。\n *\n * 流程编排只依赖 search/domain/i18n，不认识 DSH 也不生成 Markdown；\n * 旋钮档位在 dials.js，推理规则在 reasoning.js。\n */\n\nimport { LIMITS, SEARCH_CONFIG } from '../config.js'\nimport { SEVERITY_ORDER } from '../i18n/index.js'\nimport { getDomainRows } from '../repo/store.js'\nimport { search, searchStack } from '../search/retriever.js'\nimport { resolveDial } from './dials.js'\nimport { applyReasoning } from './reasoning.js'\nimport { buildColors } from './colors.js'\n\n/** 按风格优先级挑选最佳匹配（对应 _select_best_match） */\nfunction selectBestMatch(results, priorityKeywords) {\n  if (!results.length) return null\n  if (!priorityKeywords || !priorityKeywords.length) return results[0]\n\n  // 1. 风格名精确包含\n  for (const priority of priorityKeywords) {\n    const p = priority.toLowerCase().trim()\n    for (const result of results) {\n      const styleName = String(result['Style Category'] || '').toLowerCase()\n      if (p && (styleName.includes(p) || p.includes(styleName))) return result\n    }\n  }\n  // 2. 字段打分\n  const scored = results.map(result => {\n    let score = 0\n    const resultStr = JSON.stringify(result).toLowerCase()\n    for (const kw of priorityKeywords) {\n      const k = kw.toLowerCase().trim()\n      if (!k) continue\n      if (String(result['Style Category'] || '').toLowerCase().includes(k)) score += 10\n      else if (String(result['Keywords'] || '').toLowerCase().includes(k)) score += 3\n      else if (resultStr.includes(k)) score += 1\n    }\n    return { score, result }\n  })\n  scored.sort((a, b) => b.score - a.score)\n  return scored[0].score > 0 ? scored[0].result : results[0]\n}\n\n/**\n * 兜底时优先补「任何新界面都用得上」的类别，而不是按数据文件顺序抓。\n * 这些类别对新建页面普遍成立；Animation / Performance / Content 更偏场景，\n * 只在检索命中时才进来。\n */\nconst GENERIC_UX_CATEGORIES = ['Accessibility', 'Layout', 'Forms', 'Feedback', 'Navigation', 'Interaction']\n\n/**\n * 收集 UX 规范要点，保证条数下限。\n *\n * 单次 `search(用户原话, 'ux')` 不可靠：ux 域语料是英文的，整句中文查询只能靠\n * CJK 二元切分偶然命中，「财务 数据看板 深色」这类查询常常只回 1–2 条，换个措辞\n * 就可能 0 条。分三级取：\n *   1. 原话检索；\n *   2. 不足则用「已识别的产品类别」（英语，与语料同语言）二次检索；\n *   3. 仍不足则从 ux 全库按「通用类别 → 严重度」补足——宁可给通用要点，\n *      也不要让这一段消失。\n * 合并时以 `类别|问题` 去重，保留首次命中的相关度。\n *\n * 注意：二次检索**不拼风格名**。风格名描述视觉（如 \"SaaS Mobile Boutique\"），\n * 其中的 \"Mobile\" 会意外命中 \"Mobile Keyboards\" 这类无关规则，反而降低相关性。\n * @param {{ query: string, category: string, limit: number }} options\n * @returns {Array<{ row: object, score: number }>}\n */\nfunction collectUxGuidelines({ query, category, limit }) {\n  const seen = new Map()\n  const add = ({ row, score }) => {\n    const key = `${row.Category || ''}|${row.Issue || ''}`\n    if (!seen.has(key)) seen.set(key, { row, score })\n  }\n\n  // 跳过 retriever 的单字领域兜底（fallback: true）：那是按数据行顺序给的默认条目，\n  // 语义上属于\"没命中\"，应交给下面按通用类别排序的兜底，否则单字查询会拿到\n  // 数据文件前几行，与其它查询的兜底口径不一致。\n  for (const hit of search(query, 'ux', limit).results) {\n    if (!hit.fallback) add(hit)\n  }\n  if (seen.size < limit && category) {\n    for (const hit of search(category, 'ux', limit).results) add(hit)\n  }\n  if (seen.size < limit) {\n    // domain → repo 是允许的依赖方向。先通用类别、再按严重度，避免补进\n    // 「Auto-Play Video」这类与当前产品无关的条目。\n    const rank = row => {\n      const index = GENERIC_UX_CATEGORIES.indexOf(row.Category)\n      return index === -1 ? GENERIC_UX_CATEGORIES.length : index\n    }\n    const fallbackRows = [...getDomainRows('ux')].sort((a, b) =>\n      rank(a) - rank(b) || (SEVERITY_ORDER[a.Severity] ?? 9) - (SEVERITY_ORDER[b.Severity] ?? 9))\n    for (const row of fallbackRows) {\n      if (seen.size >= limit) break\n      add({ row, score: 0 })\n    }\n  }\n  return [...seen.values()].slice(0, limit)\n}\n\n/**\n * 生成完整设计系统建议。\n * @param {object} options\n * @param {string} options.query - 产品类型/行业/关键词（中英皆可）\n * @param {string} [options.projectName] - 项目名称\n * @param {number} [options.variance] - 1-10\n * @param {number} [options.motion] - 1-10\n * @param {number} [options.density] - 1-10\n * @param {string} [options.stack] - 技术栈键\n * @returns {object} 结构化中文设计系统\n */\nexport function generateDesignSystem({ query, projectName, variance, motion, density, stack }) {\n  const varianceInfo = resolveDial('variance', variance)\n  const motionInfo = resolveDial('motion', motion)\n  const densityInfo = resolveDial('density', density)\n\n  // Step 1: 产品搜索 → 类别\n  const productResult = search(query, 'product', SEARCH_CONFIG.product.maxResults)\n  const productResults = productResult.results\n  const category = productResults.length ? productResults[0].row['Product Type'] : 'General'\n\n  // Step 2: 推理规则\n  const reasoning = applyReasoning(category)\n  let stylePriority = reasoning.stylePriority\n  if (varianceInfo) {\n    stylePriority = [...varianceInfo.styleKeywords, ...stylePriority]\n  }\n\n  // Step 3: 多领域搜索（style 用「查询 + 优先级词」增强）\n  const styleQuery = stylePriority.length\n    ? `${query} ${stylePriority.slice(0, 2).join(' ')}`\n    : query\n  const styleSearch = search(styleQuery, 'style', SEARCH_CONFIG.style.maxResults)\n  const colorSearch = search(query, 'color', SEARCH_CONFIG.color.maxResults)\n  const landingSearch = search(query, 'landing', SEARCH_CONFIG.landing.maxResults)\n  const typographySearch = search(query, 'typography', SEARCH_CONFIG.typography.maxResults)\n\n  const styleResults = styleSearch.results\n  const colorResults = colorSearch.results\n  const typographyResults = typographySearch.results\n  const landingResults = landingSearch.results\n\n  // Step 4: 挑选最佳匹配\n  const bestStyle = selectBestMatch(styleResults.map(r => r.row), stylePriority)\n  const bestColor = colorResults.length ? colorResults[0].row : {}\n  const bestTypography = typographyResults.length ? typographyResults[0].row : {}\n  const bestLanding = landingResults.length ? landingResults[0].row : {}\n\n  // Step 5: 动效旋钮 → gsap 片段\n  let motionSnippet = null\n  if (motionInfo) {\n    const gsapResult = search(`${query} ${motionInfo.tier}`, 'gsap', 5)\n    const tiered = gsapResult.results.find(r => r.row['Intensity Tier'] === motionInfo.tier)\n    motionSnippet = tiered ? tiered.row : (gsapResult.results[0]?.row ?? null)\n  }\n\n  // Step 6: UX 规范要点（三级召回，保证条数下限）\n  const uxGuidelines = collectUxGuidelines({\n    query,\n    category,\n    limit: LIMITS.recommendUxGuidelines,\n  })\n\n  // Step 7: 技术栈规范（可选）\n  let stackGuidelines = []\n  if (stack) {\n    const stackResult = searchStack(query, stack, 3)\n    stackGuidelines = stackResult.results\n  }\n\n  const styleEffects = bestStyle ? bestStyle['Effects & Animation'] : ''\n  const keyEffects = styleEffects || reasoning.keyEffects\n\n  // 风格优先级排序（带理由的推荐顺序）\n  const styleCandidates = []\n  if (bestStyle) {\n    styleCandidates.push({\n      rank: 1,\n      reason: `符合推理规则「${reasoning.stylePriority.join(' + ') || '默认风格优先级'}」${varianceInfo ? `，且匹配「${varianceInfo.label}」取向` : ''}`,\n      ...bestStyle,\n    })\n  }\n  for (const { row, score } of styleResults) {\n    if (styleCandidates.some(c => c['Style Category'] === row['Style Category'])) continue\n    if (styleCandidates.length >= 3) break\n    styleCandidates.push({\n      rank: styleCandidates.length + 1,\n      reason: `检索命中（相关度 ${score.toFixed(2)}）`,\n      ...row,\n    })\n  }\n\n  // 反模式列表\n  const antiPatterns = reasoning.antiPatterns\n    ? reasoning.antiPatterns.split('+').map(s => s.trim()).filter(Boolean)\n    : []\n\n  const spacingScale = densityInfo ? densityInfo.spacing : null\n\n  return {\n    projectName: projectName || query,\n    category,\n    pattern: {\n      name: bestLanding?.['Pattern Name'] || reasoning.pattern,\n      sections: bestLanding?.['Section Order'] || 'Hero > Features > CTA',\n      ctaPlacement: bestLanding?.['Primary CTA Placement'] || 'Above fold',\n      colorStrategy: bestLanding?.['Color Strategy'] || '',\n      conversion: bestLanding?.['Conversion Optimization'] || '',\n    },\n    styles: styleCandidates,\n    colors: buildColors(bestColor, category),\n    typography: {\n      pairingName: bestTypography?.['Font Pairing Name'] || '',\n      category: bestTypography?.Category || '',\n      heading: bestTypography?.['Heading Font'] || 'Inter',\n      body: bestTypography?.['Body Font'] || 'Inter',\n      mood: bestTypography?.['Mood/Style Keywords'] || reasoning.typographyMood,\n      bestFor: bestTypography?.['Best For'] || '',\n      googleFontsUrl: bestTypography?.['Google Fonts URL'] || '',\n      cssImport: bestTypography?.['CSS Import'] || '',\n      tailwindConfig: bestTypography?.['Tailwind Config'] || '',\n      notes: bestTypography?.Notes || '',\n    },\n    keyEffects,\n    antiPatterns,\n    reasoning: {\n      colorMood: reasoning.colorMood,\n      typographyMood: reasoning.typographyMood,\n      severity: reasoning.severity,\n      decisionRules: reasoning.decisionRules,\n      stylePriority: reasoning.stylePriority,\n      recommendedPattern: reasoning.pattern,\n    },\n    uxGuidelines: uxGuidelines.map(({ row, score }) => ({\n      category: row.Category || '',\n      issue: row.Issue || '',\n      platform: row.Platform || '',\n      description: row.Description || '',\n      do: row.Do || '',\n      dont: row[\"Don't\"] || '',\n      severity: row.Severity || '',\n      score,\n    })),\n    stackGuidelines: stackGuidelines.map(({ row, score }) => ({\n      category: row.Category || '',\n      guideline: row.Guideline || '',\n      description: row.Description || '',\n      do: row.Do || '',\n      dont: row[\"Don't\"] || '',\n      severity: row.Severity || '',\n      docsUrl: row['Docs URL'] || '',\n      score,\n    })),\n    dials: {\n      variance: varianceInfo ? varianceInfo.value : null,\n      varianceLabel: varianceInfo ? varianceInfo.label : null,\n      motion: motionInfo ? motionInfo.value : null,\n      motionLabel: motionInfo ? motionInfo.label : null,\n      density: densityInfo ? densityInfo.value : null,\n      densityLabel: densityInfo ? densityInfo.label : null,\n    },\n    motionSnippet: motionSnippet ? {\n      category: motionSnippet.Category || '',\n      intensityTier: motionSnippet['Intensity Tier'] || '',\n      trigger: motionSnippet.Trigger || '',\n      duration: motionSnippet.Duration || '',\n      easing: motionSnippet.Easing || '',\n      snippet: motionSnippet['GSAP Snippet'] || '',\n      frameworkNotes: motionSnippet['Framework Notes'] || '',\n      do: motionSnippet.Do || '',\n      dont: motionSnippet[\"Don't\"] || '',\n      performanceNotes: motionSnippet['Performance Notes'] || '',\n    } : null,\n    spacingScale,\n    implementationChecklist: bestStyle?.['Implementation Checklist']\n      ? String(bestStyle['Implementation Checklist']).split(/[;；\\n]+|[,，]\\s*☐/).map(s => s.replace(/^[\\s☐•\\-]+/, '').trim()).filter(Boolean)\n      : [],\n    designSystemVariables: bestStyle?.['Design System Variables'] || '',\n  }\n}\n\n/** 供 Web UI / 模型渲染的简洁设计令牌摘要 */\nexport function summarizeDesignSystem(ds) {\n  const colors = ds.colors\n  return {\n    projectName: ds.projectName,\n    category: ds.category,\n    style: ds.styles[0]?.['Style Category'] || '',\n    styleType: ds.styles[0]?.Type || '',\n    palette: {\n      primary: colors.primary,\n      accent: colors.accent,\n      background: colors.background,\n      foreground: colors.foreground,\n      muted: colors.muted,\n      border: colors.border,\n    },\n    typography: `${ds.typography.heading} / ${ds.typography.body}`,\n    pattern: ds.pattern.name,\n    keyEffects: ds.keyEffects,\n    spacing: ds.spacingScale || null,\n  }\n}\n"
    },
    {
      "path": "lib/domain/review.js",
      "content": "/**\n * review.js — UX 审查构建（L3 业务层）\n *\n * 从 ux / web / react 三个领域检索规范，按严重度去重排序；\n * 通用检查清单在 checklist.js（数据与算法分离）。\n */\n\nimport { LIMITS } from '../config.js'\nimport { SEVERITY_ORDER } from '../i18n/index.js'\nimport { search, searchStack } from '../search/retriever.js'\nimport { STACKS } from '../repo/stacks.js'\nimport { QUICK_REFERENCE_CHECKLIST } from './checklist.js'\n\n/**\n * 工具入参 platform → 规则口径分组。\n * `desktop` 归入 web：库里没有桌面专属规则（ux 域的 Platform 只有 Web/All/Mobile/VisionOS），\n * 桌面端适用的是同一批 Web 规则。\n */\nconst PLATFORM_GROUPS = {\n  web: 'web',\n  desktop: 'web',\n  mobile: 'mobile',\n  'react-native': 'mobile',\n  flutter: 'mobile',\n}\n\n/**\n * 数据行里的 Platform 取值 → 规则口径分组。\n * `All` 是通配（任何平台都适用），单独标记避免被降权。\n */\nconst ROW_GROUPS = {\n  all: '*',\n  web: 'web',\n  mobile: 'mobile',\n  'ios/android/react native': 'mobile',\n  'react/next.js': 'web',\n  visionos: 'spatial',\n}\n\n/** 平台不匹配时的降权系数（软过滤：保留但不抢占前排）。 */\nconst MISMATCH_PENALTY = 0.5\n\nfunction rowGroup(value) {\n  return ROW_GROUPS[String(value || '').toLowerCase().trim()] || 'other'\n}\n\n/**\n * 构建 UX 审查清单。\n * @param {object} options\n * @param {string} options.target - 审查对象描述（如「移动端登录表单」「数据分析看板」）\n * @param {string} [options.platform] - web / mobile / desktop / react-native / flutter\n * @param {number} [options.maxRules] - 检索到的具体规范条数上限\n * @returns {object} 结构化中文审查清单\n */\nexport function buildReview({ target, platform = 'web', maxRules = LIMITS.defaultReviewRules }) {\n  const query = `${target} ${platform}`\n  const sources = ['ux', 'web', 'react']\n  const targetGroup = PLATFORM_GROUPS[platform] || 'web'\n\n  const collected = []\n  for (const domain of sources) {\n    const result = search(query, domain, LIMITS.reviewRulesPerDomain)\n    for (const { row, score } of result.results) {\n      const severity = SEVERITY_ORDER[row.Severity] !== undefined ? row.Severity : 'Medium'\n      const group = rowGroup(row.Platform)\n      // 软过滤：平台不符的规则降权而不是丢弃——用户可能确实需要跨平台建议，\n      // 但它不应挤掉本平台规则。\n      const weight = group === '*' || group === targetGroup ? 1 : MISMATCH_PENALTY\n      collected.push({\n        category: row.Category || '',\n        issue: row.Issue || row.Guideline || '',\n        platform: row.Platform || platform,\n        description: row.Description || '',\n        do: row.Do || '',\n        dont: row[\"Don't\"] || '',\n        severity,\n        source: domain,\n        score: score * weight,\n      })\n    }\n  }\n\n  // 目标平台本身就是技术栈（react-native / flutter）时，补该栈的框架规范，\n  // 让这两个枚举值不只是「mobile 的同义词」。这些规则是该平台的专属规范，\n  // 不参与平台降权（用户已经点名了这个平台）。\n  if (STACKS.includes(platform)) {\n    const stackResult = searchStack(query, platform, LIMITS.reviewRulesPerDomain)\n    for (const { row, score } of stackResult.results || []) {\n      const severity = SEVERITY_ORDER[row.Severity] !== undefined ? row.Severity : 'Medium'\n      collected.push({\n        category: row.Category || '',\n        issue: row.Guideline || row.Issue || '',\n        platform,\n        description: row.Description || '',\n        do: row.Do || '',\n        dont: row[\"Don't\"] || '',\n        severity,\n        source: platform,\n        score,\n      })\n    }\n  }\n\n  // 去重（同一 issue 只保留严重度最高的）\n  const seen = new Map()\n  for (const rule of collected) {\n    const key = `${rule.category}|${rule.issue}`\n    const prev = seen.get(key)\n    if (!prev || (SEVERITY_ORDER[rule.severity] ?? 9) < (SEVERITY_ORDER[prev.severity] ?? 9)) {\n      seen.set(key, rule)\n    }\n  }\n  const unique = [...seen.values()]\n\n  // 严重度排序：Critical > High > Medium > Low，同级按相关度\n  unique.sort((a, b) => {\n    const d = (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9)\n    if (d !== 0) return d\n    return b.score - a.score\n  })\n\n  const priorityRules = unique.slice(0, maxRules)\n  const bySeverity = { Critical: 0, High: 0, Medium: 0, Low: 0 }\n  for (const rule of priorityRules) {\n    bySeverity[rule.severity] = (bySeverity[rule.severity] || 0) + 1\n  }\n\n  return {\n    target,\n    platform,\n    summary: {\n      matchedRules: priorityRules.length,\n      bySeverity,\n      checklistSections: QUICK_REFERENCE_CHECKLIST.length,\n    },\n    priorityRules,\n    checklist: QUICK_REFERENCE_CHECKLIST,\n  }\n}\n"
    },
    {
      "path": "lib/search/retriever.js",
      "content": "/**\n * retriever.js — BM25 检索门面（L2）\n *\n * 屏蔽「领域配置 + BM25 引擎 + 数据存储」三者的协作文节：\n *   search / searchStack / detectDomain / 按行数组缓存的索引。\n */\n\nimport { BM25, tokenize } from './bm25.js'\nimport { DOMAIN_CONFIG, DOMAIN_MATCHERS } from '../repo/domains.js'\nimport { getDomainRows, getFontRows, getStackRows } from '../repo/store.js'\nimport { STACK_OUTPUT_COLS, STACK_SEARCH_COLS, STACKS } from '../repo/stacks.js'\nimport { expandQuery, ZH_SHORT_ALIASES } from '../i18n/index.js'\nimport { LIMITS, RETRIEVAL } from '../config.js'\n\n// ---------- BM25 索引缓存（按行数组） ----------\nconst _indexCache = new Map()\n\n/**\n * 把「原查询 + 别名扩展」拆成带权重的 token 表。\n *\n * 为什么在 token 层而不是在字符串层去重：`expandQuery` 去重的是词典条目\n * （`dark mode` / `dark` / `dark-mode` 是三个不同字符串），拼成查询串后会被\n * tokenize 拆成同一个 `dark`，于是同一概念被计多次，主属性词被稀释。\n *\n * 原查询 token 权重 1.0，扩展 token 权重 0.6（见 config.RETRIEVAL）。\n * 导出以便测试直接断言权重表，而不必从排序结果反推。\n * @param {string} query\n * @returns {{ expanded: string, terms: Map<string, number> }}\n */\nexport function buildQueryTerms(query) {\n  const expanded = expandQuery(query)\n  const terms = new Map()\n  for (const token of new Set(tokenize(query))) {\n    terms.set(token, RETRIEVAL.primaryWeight)\n  }\n  for (const token of tokenize(expanded)) {\n    if (!terms.has(token)) terms.set(token, RETRIEVAL.expansionWeight)\n  }\n  return { expanded, terms }\n}\n\nfunction searchRows(rows, searchCols, terms, maxResults, rowFilter = null) {\n  if (!rows || rows.length === 0) return []\n  const documents = rows.map(row => searchCols.map(col => row[col] ?? '').join(' '))\n  let bm25 = _indexCache.get(rows)\n  if (!bm25) {\n    bm25 = new BM25()\n    bm25.fit(documents)\n    _indexCache.set(rows, bm25)\n  }\n  const ranked = bm25.scoreTerms(terms)\n  const results = []\n  for (const { index, score } of ranked) {\n    if (results.length >= maxResults) break\n    if (score > 0 && (!rowFilter || rowFilter(rows[index]))) {\n      results.push({ row: rows[index], score })\n    }\n  }\n  return results\n}\n\n/** 上游 style/stacks 用 Status=deprecated 标记已废弃条目；默认不返回。 */\nfunction isDeprecated(row) {\n  return String(row?.Status || '').toLowerCase() === 'deprecated'\n}\n\n/** 查询里显式提到 legacy / deprecated 时，允许返回废弃条目（与上游一致）。 */\nfunction asksForLegacy(query) {\n  return /\\b(?:legacy|deprecated)\\b/i.test(String(query))\n}\n\n/**\n * 废弃条目的统一召回策略（style 与 stack 一致，不可再分域处理）：\n * 默认排除 Status=deprecated 的行；当查询里显式提到 legacy / deprecated，\n * 或调用方显式传 `includeDeprecated: true` 时放行。\n * @param {string} query\n * @param {{ includeDeprecated?: boolean }} [options]\n * @returns {((row: object) => boolean) | null}\n */\nfunction deprecatedFilter(query, options = {}) {\n  if (options.includeDeprecated === true || asksForLegacy(query)) return null\n  return row => !isDeprecated(row)\n}\n\nconst SINGLE_CJK_RE = /^[\\u4e00-\\u9fff]$/\n\n/**\n * 查询是否是一个**已登记**的汉字（如「图」「色」）。\n *\n * 用单字表判定而不用「是否单字」判定：像「表」「页」这种一字多义的字故意不收\n * （见 short.zh.js），此时应如实返回空结果，而不是拿某个领域的默认条目冒充答案。\n * @param {string} query\n */\nfunction isKnownSingleCjkQuery(query) {\n  const trimmed = String(query).trim()\n  return SINGLE_CJK_RE.test(trimmed) && Object.hasOwn(ZH_SHORT_ALIASES, trimmed)\n}\n\n/** 按列挑选字段（完整输出时合并 search + output 列）。 */\nfunction pick(row, cols) {\n  const out = {}\n  for (const col of cols) {\n    if (col in row) out[col] = row[col]\n  }\n  return out\n}\n\n/**\n * 领域搜索。\n * @param {string} query - 查询（中文自动扩展）\n * @param {string|null} domain - 领域键；缺省时自动检测\n * @param {number} maxResults\n * @param {{ includeDeprecated?: boolean }} [options]\n * @returns {{ domain: string, query: string, count: number, results: Array<{row: object, score: number}> }}\n */\nexport function search(query, domain = null, maxResults = LIMITS.defaultResults, options = {}) {\n  const effectiveDomain = domain || detectDomain(query)\n  const config = DOMAIN_CONFIG[effectiveDomain] || DOMAIN_CONFIG.style\n  const rows = effectiveDomain === 'google-fonts'\n    ? getFontRows()\n    : getDomainRows(effectiveDomain)\n\n  const { expanded, terms } = buildQueryTerms(query)\n  const rowFilter = deprecatedFilter(query, options)\n  const matched = searchRows(rows, config.searchCols, terms, maxResults, rowFilter)\n  let results = matched.map(({ row, score }) => ({ row: pick(row, config.outputCols), score }))\n\n  // 已登记的单字查询（如「色」）扩展后仍可能零命中：该领域语料是按产品类型/\n  // 场景组织的，未必含有扩展词。此时返回领域内的默认条目，比返回空数组更有用\n  // ——空数组会被模型解读成「设计库里没有这个领域」。\n  // 仅对 short.zh.js 里登记过的字生效，未登记的单字照常返回空。\n  if (results.length === 0 && isKnownSingleCjkQuery(query)) {\n    results = rows\n      .filter(row => !rowFilter || rowFilter(row))\n      .slice(0, maxResults)\n      .map(row => ({ row: pick(row, config.outputCols), score: 0, fallback: true }))\n  }\n\n  return {\n    domain: effectiveDomain,\n    query,\n    expandedQuery: expanded,\n    count: results.length,\n    results,\n  }\n}\n\n/**\n * 技术栈搜索。\n * @param {string} query\n * @param {string} stack - 技术栈键（见 STACKS）\n * @param {number} maxResults\n * @param {{ includeDeprecated?: boolean }} [options]\n */\nexport function searchStack(query, stack, maxResults = LIMITS.defaultResults, options = {}) {\n  if (!STACKS.includes(stack)) {\n    return {\n      error: `未知技术栈: ${stack}。可用: ${STACKS.join(', ')}`,\n      stack,\n      count: 0,\n      results: [],\n    }\n  }\n  const rows = getStackRows(stack)\n  const { expanded, terms } = buildQueryTerms(query)\n  const rowFilter = deprecatedFilter(query, options)\n  const matched = searchRows(rows, STACK_SEARCH_COLS, terms, maxResults, rowFilter)\n  return {\n    domain: 'stack',\n    stack,\n    query,\n    expandedQuery: expanded,\n    count: matched.length,\n    results: matched.map(({ row, score }) => ({ row: pick(row, STACK_OUTPUT_COLS), score })),\n  }\n}\n\n/**\n * 自动检测最相关的领域。\n * @param {string} query\n * @returns {string}\n */\nexport function detectDomain(query) {\n  const q = expandQuery(query).toLowerCase()\n  let best = 'style'\n  let bestScore = 0\n  for (const { domain, wordRes, substrings } of DOMAIN_MATCHERS) {\n    let score = 0\n    for (const re of wordRes) { if (re.test(q)) score += 1 }\n    for (const s of substrings) { if (q.includes(s)) score += 1 }\n    if (score > bestScore) { bestScore = score; best = domain }\n  }\n  return best\n}\n"
    },
    {
      "path": "lib/search/bm25.js",
      "content": "/**\n * bm25.js — BM25 文本检索引擎\n *\n * 移植自 ui-ux-pro-max 源技能的 core.py（纯标准库实现），并增强：\n *  - 中文分词：对连续 CJK 片段做二元切分（bigram），使中文内容可参与检索\n *  - 保持与 Python 版一致的 k1=1.5 / b=0.75 参数与 IDF 公式\n *\n * 用法：\n *   const bm25 = new BM25()\n *   bm25.fit(documents)          // documents: string[]\n *   const ranked = bm25.score(query)  // [{ index, score }] 降序\n */\n\nconst CJK_RE = /[\\u4e00-\\u9fff\\u3400-\\u4dbf\\uf900-\\ufaff\\u3040-\\u30ff\\uac00-\\ud7af]/\n\n/** 保留数字与字母（含下划线），其余视为分隔符 */\nfunction isWordChar(ch) {\n  return /[a-z0-9_]/.test(ch)\n}\n\nfunction isCJK(ch) {\n  return CJK_RE.test(ch)\n}\n\n/**\n * 分词：小写化 → 去标点 → 按空白/分隔切分 → 保留长度 >= 2 的词；\n * 对包含 CJK 的片段额外产出二元切分。\n *\n * 长度过滤只对拉丁词生效：单个汉字有检索价值（「图」→ 图表），单个字母没有\n * （否则 \"a\"/\"i\" 这类会污染索引）。此前统一 `length >= 2` 把上面专门为\n * 单字 CJK 写的分支变成了死代码。\n * @param {string} text\n * @returns {string[]}\n */\nexport function tokenize(text) {\n  const str = String(text).toLowerCase()\n  const tokens = []\n  let i = 0\n  const n = str.length\n  let buf = ''\n  while (i < n) {\n    const ch = str[i]\n    if (isWordChar(ch)) {\n      buf += ch\n      i += 1\n      continue\n    }\n    if (isCJK(ch)) {\n      if (buf) { tokens.push(buf); buf = '' }\n      // 收集连续 CJK 片段\n      let cjk = ''\n      while (i < n && isCJK(str[i])) { cjk += str[i]; i += 1 }\n      if (cjk.length >= 2) {\n        // 二元切分\n        for (let k = 0; k < cjk.length - 1; k++) tokens.push(cjk.slice(k, k + 2))\n        // 也保留整段（便于精确匹配）\n        tokens.push(cjk)\n      } else if (cjk.length === 1) {\n        tokens.push(cjk)\n      }\n      continue\n    }\n    if (buf) { tokens.push(buf); buf = '' }\n    i += 1\n  }\n  if (buf) tokens.push(buf)\n  return tokens.filter(t => t.length >= 2 || (t.length === 1 && isCJK(t)))\n}\n\n/**\n * 统计 token 权重：同一 token 出现两次即权重 2（保留 BM25 的 qtf 语义）。\n * @param {string[]} tokens\n * @returns {Map<string, number>}\n */\nexport function tokenWeights(tokens) {\n  const weights = new Map()\n  for (const token of tokens) weights.set(token, (weights.get(token) || 0) + 1)\n  return weights\n}\n\nexport class BM25 {\n  /**\n   * @param {number} k1 - 词频饱和参数（默认 1.5）\n   * @param {number} b - 文档长度归一化参数（默认 0.75）\n   */\n  constructor(k1 = 1.5, b = 0.75) {\n    this.k1 = k1\n    this.b = b\n    this.corpus = []\n    this.docLengths = []\n    this.avgdl = 0\n    this.idf = new Map()\n    this.docFreqs = new Map()\n    this.N = 0\n  }\n\n  /** 构建索引 */\n  fit(documents) {\n    this.corpus = documents.map(doc => tokenize(doc))\n    this.N = this.corpus.length\n    if (this.N === 0) return\n    this.docLengths = this.corpus.map(doc => doc.length)\n    this.avgdl = this.docLengths.reduce((a, b) => a + b, 0) / this.N\n\n    this.docFreqs = new Map()\n    for (const doc of this.corpus) {\n      const seen = new Set()\n      for (const word of doc) {\n        if (!seen.has(word)) {\n          this.docFreqs.set(word, (this.docFreqs.get(word) || 0) + 1)\n          seen.add(word)\n        }\n      }\n    }\n\n    this.idf = new Map()\n    for (const [word, freq] of this.docFreqs) {\n      this.idf.set(word, Math.log((this.N - freq + 0.5) / (freq + 0.5) + 1))\n    }\n  }\n\n  /**\n   * 对所有文档打分，返回按分数降序的 [{ index, score }]。\n   * @param {string} query\n   * @returns {Array<{index: number, score: number}>}\n   */\n  score(query) {\n    return this.scoreTerms(tokenWeights(tokenize(query)))\n  }\n\n  /**\n   * 按 token 权重打分（供「原查询 vs 别名扩展词」不等权使用）。\n   * @param {Map<string, number>} terms - token → 权重\n   * @returns {Array<{index: number, score: number}>}\n   */\n  scoreTerms(terms) {\n    const scores = []\n    const idf = this.idf\n    const k1 = this.k1\n    const b = this.b\n\n    for (let idx = 0; idx < this.corpus.length; idx++) {\n      const doc = this.corpus[idx]\n      const docLen = this.docLengths[idx]\n      const termFreqs = new Map()\n      for (const word of doc) termFreqs.set(word, (termFreqs.get(word) || 0) + 1)\n\n      let score = 0\n      for (const [token, weight] of terms) {\n        const idfVal = idf.get(token)\n        if (idfVal === undefined) continue\n        const tf = termFreqs.get(token) || 0\n        const numerator = tf * (k1 + 1)\n        const denominator = tf + k1 * (1 - b + b * docLen / this.avgdl)\n        score += weight * idfVal * numerator / denominator\n      }\n      scores.push({ index: idx, score })\n    }\n\n    return scores.sort((a, b) => b.score - a.score)\n  }\n}\n"
    },
    {
      "path": "lib/repo/store.js",
      "content": "/**\n * store.js — 内置数据访问唯一入口（L2）\n *\n * 全仓唯一出现 `data/*.json` 路径的地方：惰性单例加载 index.json / fonts.json。\n * 将来换数据源（远程、压缩包、分片）只改这一个文件。\n */\n\nimport { readFileSync } from 'node:fs'\n\nconst INDEX_URL = new URL('../../data/index.json', import.meta.url)\nconst FONTS_URL = new URL('../../data/fonts.json', import.meta.url)\n\nlet _db = null\n\nfunction loadDb() {\n  if (_db) return _db\n  const raw = readFileSync(INDEX_URL, 'utf8')\n  _db = JSON.parse(raw)\n  return _db\n}\n\n/** 访问内置数据库 */\nexport function getDb() {\n  return loadDb()\n}\n\n/** 领域数据行 */\nexport function getDomainRows(domain) {\n  const db = loadDb()\n  return db.domains[domain] || []\n}\n\n/** 技术栈数据行 */\nexport function getStackRows(stack) {\n  const db = loadDb()\n  return db.stacks[stack] || []\n}\n\n/** 推理规则行 */\nexport function getReasoningRows() {\n  return loadDb().reasoning || []\n}\n\nlet _fonts = null\nlet _fontsLoaded = false\n\n/** Google Fonts 行（1.1MB，首次访问才加载） */\nexport function getFontRows() {\n  if (_fontsLoaded) return _fonts\n  const raw = readFileSync(FONTS_URL, 'utf8')\n  const parsed = JSON.parse(raw)\n  _fonts = parsed.googleFonts || []\n  _fontsLoaded = true\n  return _fonts\n}\n"
    },
    {
      "path": "skills/ui-ux-pro-max/SKILL.md",
      "content": "---\nname: ui-ux-pro-max\ndescription: UI/UX 设计智能库：通过 design_recommend / design_review / design_search 工具获取中文优先、带理由的设计系统建议（风格/配色/字体/UX 规范/图表/技术栈），覆盖 88 种设计风格、192 个调色板、74 组字体搭配、119 条 UX 规范、25 种图表类型与 22 个技术栈。数据完全内置、离线可用。\nwhenToUse: 新建或改造界面、评审 UX、选风格/配色/字体、查图表/动效/技术栈规范时使用。\n---\n\n# UI/UX 设计智能库（ui-ux-pro-max）\n\n为 Web / 移动端 / 桌面应用提供设计智能：**88 种设计风格、192 个调色板、74 组字体搭配、119 条 UX 规范、25 种图表类型**，覆盖 **22 个技术栈**。数据库完全内置在插件中（无网络、无 Python 依赖）。三个工具各有分工，先选对工具再查：\n\n## 先选对工具\n\n| 你在做什么 | 用哪个 | 说明 |\n|---|---|---|\n| 新项目/新页面，要一套完整设计系统 | `design_recommend` | 风格、配色、字体、落地页、UX 要点一次给全 |\n| 评审已有界面、查无障碍/交互/性能问题 | `design_review` | 按严重度排序，附交付前检查清单 |\n| 查某类素材或细节（图表/图标/动效/技术栈/产品类型） | `design_search` | 定向检索，结果更集中 |\n| 只输入一个汉字（`图`/`色`/`字`/`动`） | `design_search` | 唯一支持单字领域兜底的工具 |\n\n**不要把 `design_recommend` 当搜索框。** 它会先用 `product` 域判定产品类别，单字或过短的查询容易得到偶然类别（例如 `色` 会落到 \"Digital Signage / Kiosk\"），再据此生成整套建议就会跑偏。查素材请用 `design_search`。\n\n## 使用流程\n\n### 1. 从零开始做界面 → `design_recommend`\n\n新页面、新项目先用它拿一整套方案，再按需补检索：\n\n```\ndesign_recommend(query: \"财务 数据看板 深色 高密度\", projectName: \"财务中台\", stack: \"react\")\ndesign_recommend(query: \"AI 搜索 极简 留白\", projectName: \"AI Search\", variance: 8, motion: 6, density: 8)\n```\n\n- `query`：写「产品类型 + 行业 + 气质/功能」，**至少两个词**，最想强调的放最前；单个汉字或「好看一点」这类泛词会先被误判类别。\n  - 中文直接写中文即可（「财务 数据看板 深色」）；但 `gsap` / `react` / `web` / `google-fonts` 的语料是英文，留英文术语命中更准（`scroll reveal`、`memo`）。\n  - 中文会映射到英文语料（「金融」→ fintech、「毛玻璃」→ glassmorphism）；检索按 token 打分，原词权重 1.0、扩展词 0.6，所以堆同义词不会更准——`\"毛玻璃 深色\"` 与 `\"毛玻璃 玻璃 深色 暗色\"` 结果一样。\n- `stack`（可选）：附加该技术栈的实现规范（react / nextjs / vue / flutter / swiftui / javafx / wpf / winui / avalonia / uno / uwp / threejs / angular / laravel / svelte / astro / nuxtjs / nuxt-ui / html-tailwind / shadcn / jetpack-compose / react-native）。\n- 三个 1-10 旋钮（可选）：\n  - `variance`：1=居中/极简，10=大胆/不对称（粗野主义、Bento 网格）\n  - `motion`：1=克制，10=复杂编排；会附加匹配的 GSAP 动效方案\n  - `density`：1=宽松（24-96px 间距），10=紧凑/看板（8-32px 间距）\n- **返回结构**：推荐风格（按优先级排序、带理由）→ 配色方案（HEX 令牌 + CSS 变量）→ 字体搭配 → 落地页模式 → UX 规范要点 → 反模式 → 决策规则 →（可选）技术栈规范 / GSAP 动效 / 间距刻度 / 实现清单。\n- **UX 规范要点**：固定不少于 3 条；命中不足时会用通用类别（Accessibility/Layout/Forms 等）兜底。看到偏通用的条目时把它当基线，不要当作\"该产品专属结论\"。\n\n### 2. 已有界面，想知道哪里不对 → `design_review`\n\n连同**页面、关键交互、出错的现象**一起描述，得到按严重度排序的规范 + 交付前检查清单：\n\n```\ndesign_review(target: \"移动端登录页，提交后没有任何反馈\", platform: \"mobile\")\ndesign_review(target: \"数据看板首屏加载慢，图表出来晚\", platform: \"web\", maxRules: 12)\n```\n\n- `target` 写具体：页面/组件 + 关键交互 + 状态或现象（「结算页优惠券输入 错误态」比「结算页」有用得多）。\n- `platform` 只影响**同严重度内的先后**：**严重度仍是第一排序键**，匹配平台的规则靠前，不匹配的 ×0.5 降权但**保留**（不是硬过滤）。`desktop` 按 `web` 口径处理（库内没有桌面专属规则）；`react-native` / `flutter` 会额外追加该栈的框架规范。\n\n把返回的规则当作检查清单逐条核对；若某条是刻意例外，在汇报里说明而不是悄悄跳过。\n\n### 3. 只缺一块：定点补 → `design_search`\n\n| 缺什么 | `domain` | 示例 |\n|---|---|---|\n| 换一种风格 | `style` | `design_search(\"毛玻璃 深色\", \"style\")` |\n| 定配色 | `color` | `design_search(\"金融 信任蓝\", \"color\")` |\n| 选图表 | `chart` | `design_search(\"实时监控 趋势\", \"chart\")` |\n| 选字体 | `typography` | `design_search(\"高端 优雅\", \"typography\")` |\n| 表单/无障碍规范 | `ux` | `design_search(\"表单 校验 无障碍\", \"ux\")` |\n| 排落地页 | `landing` | `design_search(\"首屏 用户评价 定价\", \"landing\")` |\n| 判断产品类型 | `product` | `design_search(\"金融 数据看板\", \"product\")` |\n| 找图标 | `icons` | `design_search(\"导航 设置\", \"icons\")` |\n| 写动效 | `gsap` | `design_search(\"scroll reveal stagger\", \"gsap\")` |\n| 治列表卡顿 | `react` | `design_search(\"列表 卡顿 memo\", \"react\")` |\n| 修移动端遮挡 | `web` | `design_search(\"safe area 安全区\", \"web\")` |\n| 挑 Google 字体 | `google-fonts` | `design_search(\"monospace 等宽 可变\", \"google-fonts\")` |\n| 查框架规范 | `stack` 参数 | `design_search(\"长列表 性能 导航\", stack: \"react-native\")` |\n\n`domain` 可省略（自动识别），但已知领域时显式传入更稳；`maxResults` 取 1-8，默认 3。\n\n**单字查询**只登记了 4 个语义没有争议的字：\n\n| 字 | 领域 | 说明 |\n|---|---|---|\n| `图` | chart | 图表类型与选型建议 |\n| `色` | color | 调色板与配色 |\n| `字` | typography | 字体搭配 |\n| `动` | ux | 动效/动画相关规范 |\n\n`表`（表单/表格）、`页`（页面/落地页）这类一字多义的字**故意不收录**——宁可不猜，也不把查询带到错误领域。未登记的单字可能返回空结果，这不代表库里没有该领域。\n\n已登记单字在目标领域零命中时会返回该领域的**默认条目**，结构化结果里带 `fallback: true`，Markdown 会注明「默认条目」。这类结果只作方向参考，不要当成精确命中。\n\n检索默认排除上游标记为 `deprecated` 的条目（9 条风格、部分技术栈规范）；若确实要沿用旧项目的遗留风格，在查询里带上 `legacy` / `deprecated` 即可召回（风格与技术栈同一套判定）。需要“正常查询但包含废弃条目”时，给 `design_search` 传 `includeDeprecated: true`；它只放行 `Status=deprecated` 的行，不改变查询词与排序。\n\n## 结果解读（避免误读）\n\n- `score` 是**单次查询内**的 BM25 相对分，不是百分比或置信度；不要跨领域比较，也不要把 `0.00` 当成\"完全无关\"（领域兜底条目就是 0）。\n- **空结果 = 本次查询没匹配**，不等于库里没有这个领域。改用 2-4 个字的关键词、英文术语，或换一个 `domain` 重试；已知领域时显式传入。\n- 领域自动识别可能把查询带到相邻领域（例如「动」→ ux 的动效规范）；结果不对时显式指定 `domain`。\n- 有 `fallback: true` 的结果表示\"没精确命中、给的是领域默认条目\"，汇报时要说明，不要把它包装成检索命中。\n\n## 常见误用\n\n- 把 `platform` 当硬过滤，期待结果集只剩该平台规则。\n- 把 UX 的 3 条通用兜底要点当成产品专属结论。\n- 把空结果解释成\"设计库里没有这个领域\"。\n\n## 通用规则（专业 UI 底线）\n\n- **图标**：默认 Phosphor 图标库；优先从完整图标集选语义贴切的矢量图标，Heroicons 作备选。**禁止用 emoji 作为结构图标**；图标统一尺寸令牌（icon-sm/md/lg）、统一描边与线性/填充风格。\n- **触控**：触摸目标 ≥44×44pt（iOS）/ ≥48×48dp（Android），小图标用 hitSlop 扩展。\n- **按压反馈**：80-150ms 内给出反馈，微交互 150-300ms 且用平台原生缓动；按压态不改变布局边界。\n- **对比度**：浅色正文 ≥4.5:1；深色模式独立测试（正文 ≥4.5:1、次要文字 ≥3:1）；分隔线/状态在深浅两套主题下都可见。\n- **间距**：4/8dp 节奏，定义纵向层级（16/24/32/48）；大屏长文保持 45-75 字符行长。\n- **安全区**：遵守刘海/状态栏/手势条；滚动内容不被固定栏遮挡。\n- **语义令牌**：用语义化颜色/间距令牌，禁止逐屏硬编码 hex。\n- **状态完备**：空状态、加载态（骨架屏）、错误态、禁用态都要设计，不能只做 happy path。\n\n## 交付前检查\n\n- [ ] 无 emoji 图标（用 SVG 矢量图标库）\n- [ ] 触摸目标达标、按压反馈清晰、cursor-pointer\n- [ ] 深浅色模式对比度都达标（独立测试，不推断）\n- [ ] 375px 小屏 + 横竖屏验证，安全区无遮挡\n- [ ] 无障碍：标签/焦点顺序/角色正确，支持 reduced-motion 与动态字体\n- [ ] 长列表虚拟化、防抖节流、避免瀑布请求\n- [ ] 表单内联校验、错误清晰、焦点管理正确\n"
    }
